int32_t __fastcall PLRSKILLS_CanUseSkillCheck(D2UnitStrc * pUnit, D2SkillStrc * pSkill) {
    uint32_t nMaxEntries;
    int32_t nCanUse = D2Common::Skills::SKILLS_CanUseSkill(pUnit, pSkill);
    if (nCanUse) {
      return nCanUse;
    }

    D2UnitStrc* pPlayerUnit_lcl = Player::GetPlayerUnit_Net();
    if (pUnit == pPlayerUnit_lcl) {
      uint32_t nEntryIdx;
      nEntryIdx = GAME::Game::GetEntryIndex();
      nMaxEntries = GAME::Game::GAME_GetSkillDelayEndFrame();
      if (nEntryIdx < nMaxEntries) {
        return 8;
      }
    }

    nCanUse = 0;
    return nCanUse;
}

